import 'package:flutter/material.dart';
import 'package:get/get.dart';

import '../service/logger_service.dart';
import '../service/theme_service.dart';
import '../theme/theme.dart';
import '../util/util.dart';

class CustomScaffold extends StatelessWidget {
  const CustomScaffold({
    required this.body,
    super.key,
    this.padding = false,
    this.bottomNavigationBar,
  });

  final Widget body;
  final Widget? bottomNavigationBar;
  final bool padding;

  @override
  Widget build(BuildContext context) {
    final CustomTheme dinasonaTheme = Get.put(ThemeService()).theme;
    return Scaffold(
      body: Expanded(
        child: Padding(
          padding: EdgeInsets.symmetric(
            horizontal: padding ? getRelativeWidth(20) : 0,
            vertical: padding ? getRelativeHeight(40) : 0,
          ),
          child: body,
        ),
      ),
      backgroundColor: dinasonaTheme.moonstone,
      bottomNavigationBar: bottomNavigationBar,
      floatingActionButton: FloatingActionButton(
        heroTag: null,
        onPressed: () {
          Get.find<LoggerService>().show();
        },
        backgroundColor: Colors.red,
        child: const Icon(Icons.logo_dev_rounded),
      ),
    );
  }
}
